/* oxlint-disable nextjs/no-img-element -- Static export: responsive variants are generated by scripts/build-images.mjs. */
import { assetPath } from '@/lib/asset-path';
import { media, type MediaId } from '@/content/media.generated';

type PictureProps = {
  id: MediaId;
  alt: string;
  /** The `sizes` attribute; describe the rendered width at each breakpoint. */
  sizes: string;
  /** Above-the-fold images load eagerly with high priority. */
  priority?: boolean;
  className?: string;
};

export function Picture({ id, alt, sizes, priority, className }: PictureProps) {
  const image = media[id];
  const srcSet = image.widths
    .map((width) => `${assetPath(`/media/${id}-${width}.webp`)} ${width}w`)
    .join(', ');
  return (
    <picture>
      <source type="image/webp" srcSet={srcSet} sizes={sizes} />
      <img
        className={className}
        src={assetPath(`/media/${image.fallback}`)}
        alt={alt}
        width={image.width}
        height={image.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : undefined}
      />
    </picture>
  );
}

/** URL of one generated variant, for CSS backgrounds, posters and social cards. */
export function mediaUrl(id: MediaId, width?: number): string {
  const image = media[id];
  const chosen = width ?? image.widths[image.widths.length - 1];
  return assetPath(`/media/${id}-${chosen}.webp`);
}
